(function () {
  "use strict";
  let registration,
    installEvent,
    pendingUpdate = false,
    preparingUpdate = false,
    offlineReady = false,
    updateRecovery = false,
    reloadRequested = false;
  let updateMessage = "",
    updateTimer;
  function text(message) {
    const el = document.getElementById("mobileStatus");
    if (el) {
      el.textContent = message;
      el.title = message;
    }
  }
  function paint() {
    if (!document.getElementById("mobileInstall")) return;
    if (location.protocol === "file:") {
      text("فایل مستقل آفلاین؛ نصب PWA از لینک امن انجام می‌شود.");
      return;
    }
    const status = offlineReady
      ? navigator.onLine
        ? "آماده اجرای آفلاین"
        : "آفلاین — اطلاعات روی دستگاه ذخیره می‌شود"
      : "در حال آماده‌سازی اجرای آفلاین…";
    text(updateMessage || status);
    document.getElementById("mobileBar").dataset.offlineReady =
      String(offlineReady);
    document.getElementById("mobileBar").dataset.updateError =
      String(!!updateMessage);
    document.getElementById("mobileInstall").hidden =
      !installEvent ||
      matchMedia("(display-mode: standalone)").matches ||
      !!navigator.standalone;
    const updateButton = document.getElementById("mobileUpdate");
    updateButton.hidden = !registration?.waiting && !pendingUpdate;
    const updateLabel = updateButton.querySelector?.("span");
    if (updateLabel)
      updateLabel.textContent = updateRecovery
        ? "بازکردن دوباره برنامه"
        : "نسخه جدید آماده است";
  }

  const installNoticeKey = "edu-manager:pwa-notice:v1";
  const isInstalled = () =>
    matchMedia("(display-mode: standalone)").matches || !!navigator.standalone;
  function rememberInstallNotice() {
    try {
      localStorage.setItem(installNoticeKey, "seen");
    } catch {}
  }
  function closeInstallNotice() {
    const d = document.getElementById("pwaWelcome");
    if (d) {
      d.close?.();
      d.remove();
    }
  }
  function paintInstallNotice() {
    const button = document.getElementById("pwaWelcomeInstall");
    if (button)
      button.textContent = installEvent
        ? "نصب برنامه روی دستگاه"
        : "راهنمای نصب روی دستگاه";
    const status = document.getElementById("pwaWelcomeStatus");
    if (status)
      status.textContent = offlineReady
        ? "✓ فایل‌های برنامه برای اجرای آفلاین ذخیره شدند."
        : "در حال دریافت فایل‌های اجرای آفلاین؛ فعلاً اینترنت را متصل نگه دارید.";
  }
  async function requestInstall() {
    if (!installEvent) {
      closeInstallNotice();
      help();
      return;
    }
    const event = installEvent;
    installEvent = null;
    try {
      await event.prompt();
      const choice = await event.userChoice;
      if (choice.outcome === "accepted") {
        rememberInstallNotice();
        closeInstallNotice();
      }
    } catch {
      closeInstallNotice();
      help();
    }
    paint();
    paintInstallNotice();
  }
  function firstVisitInstall() {
    if (location.protocol === "file:" || !isSecureContext || isInstalled())
      return;
    try {
      if (localStorage.getItem(installNoticeKey) === "seen") return;
    } catch {}
    const d = document.createElement("dialog");
    d.id = "pwaWelcome";
    d.setAttribute("aria-labelledby", "pwaWelcomeTitle");
    d.style.cssText =
      "box-sizing:border-box;direction:rtl;font-family:IRANSans,Tahoma,sans-serif;width:min(440px,calc(100% - 24px));max-height:calc(100dvh - 32px);overflow:auto;border:0;border-radius:20px;padding:24px;color:var(--theme-ink, #2d3440);background:var(--theme-surface, #fff);box-shadow:var(--theme-shadow-lg, 0 16px 64px #2d344047);line-height:1.9";
    d.innerHTML =
      '<div class="pwa-install-brand"><span class="app-brand-mark" aria-hidden="true"><img class="app-logo" src="./assets/logo3.png" width="500" height="500" alt="" decoding="async"></span><strong>کلاس‌یار</strong></div><h2 id="pwaWelcomeTitle" style="font-size:1.2rem;margin:0 0 12px">برنامه را روی دستگاهت نصب کن</h2><p>برای دسترسی از صفحه اصلی و استفاده بدون اینترنت، کلاس‌یار را نصب کن.</p><p id="pwaWelcomeStatus" role="status" aria-live="polite"></p><p style="font-size:.9rem">در آیفون و آیپد: منوی اشتراک‌گذاری (Share) ← افزودن به صفحه اصلی (Add to Home Screen). در اندروید و رایانه از دکمه نصب یا منوی مرورگر استفاده کن.</p><div style="display:flex;flex-wrap:wrap;gap:8px"><button id="pwaWelcomeInstall" type="button" style="flex:1;min-height:44px">نصب برنامه روی دستگاه</button><button id="pwaWelcomeLater" type="button" class="ghost" style="min-height:44px">فعلاً ادامه می‌دهم</button></div>';
    document.body.append(d);
    d.querySelector("#pwaWelcomeInstall").onclick = requestInstall;
    d.querySelector("#pwaWelcomeLater").onclick = () => {
      rememberInstallNotice();
      closeInstallNotice();
    };
    d.addEventListener("cancel", () => {
      rememberInstallNotice();
    });
    if (d.showModal) d.showModal();
    else d.setAttribute("open", "");
    paintInstallNotice();
  }

  function shell() {
    const bar = document.createElement("aside");
    bar.className = "mobile-bar no-print";
    bar.id = "mobileBar";
    bar.setAttribute("aria-label", "وضعیت، نصب و به‌روزرسانی برنامه");
    const icon = (path) =>
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="' +
      path +
      '"/></svg>';
    bar.innerHTML =
      '<strong>کلاس‌یار</strong><span id="mobileStatus" role="status" aria-live="polite"></span><div class="app-service-actions"><button type="button" id="mobileInstall" hidden>' +
      icon("M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5") +
      '<span>نصب برنامه</span></button><button type="button" id="mobileUpdate" hidden>' +
      icon(
        "M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1",
      ) +
      '<span>نسخه جدید آماده است</span></button><button type="button" id="mobileHelp" class="ghost">' +
      icon(
        "M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4m.1 3h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0",
      ) +
      "<span>نصب و راهنما</span></button></div>";
    document.body.prepend(bar);
    document.getElementById("mobileInstall").onclick = requestInstall;
    document.getElementById("mobileUpdate").onclick = update;
    document.getElementById("mobileHelp").onclick = help;
  }
  function help() {
    const installed =
      matchMedia("(display-mode: standalone)").matches || navigator.standalone;
    const html = window.EduOfflineHelp.html(installed);
    if (window.showModal) showModal("نصب و استفاده آفلاین", html);
    else
      alert(
        "پس از نمایش آماده اجرای آفلاین، برنامه را از منوی مرورگر روی صفحه اصلی نصب کنید.",
      );
  }
  let offlineStatusRequest = 0;
  async function status() {
    const request = ++offlineStatusRequest;
    const worker = navigator.serviceWorker.controller || registration?.active;
    if (!worker) return;
    if (worker.state !== "activated") {
      worker.addEventListener(
        "statechange",
        () => {
          if (worker.state === "activated") status();
        },
        { once: true },
      );
      return;
    }
    const channel = new MessageChannel();
    channel.port1.onmessage = (e) => {
      if (
        request !== offlineStatusRequest ||
        (navigator.serviceWorker.controller &&
          worker !== navigator.serviceWorker.controller)
      ) {
        channel.port1.close();
        return;
      }
      offlineReady = e.data?.ready === true;
      paint();
      paintInstallNotice();
      channel.port1.close();
    };
    worker.postMessage({ type: "OFFLINE_STATUS" }, [channel.port2]);
  }

  let updateLock = null;
  function lockUpdateSurface(focus) {
    updateLock = {
      focus,
      surfaces: ["app", "modal", "uiBottomNav"]
        .map((id) => document.getElementById(id))
        .filter(Boolean)
        .map((element) => ({ element, inert: element.inert })),
      controls: ["mobileHelp", "mobileInstall"]
        .map((id) => document.getElementById(id))
        .filter(Boolean)
        .map((element) => ({ element, disabled: element.disabled })),
    };
    for (const { element } of updateLock.surfaces) element.inert = true;
    for (const { element } of updateLock.controls) element.disabled = true;
  }
  function unlockUpdateSurface() {
    if (!updateLock) return;
    const previous = updateLock;
    updateLock = null;
    for (const { element, inert } of previous.surfaces) element.inert = inert;
    for (const { element, disabled } of previous.controls)
      element.disabled = disabled;
    if (
      previous.focus?.isConnected !== false &&
      !previous.focus?.closest?.("[inert]")
    )
      previous.focus?.focus?.({ preventScroll: true });
  }

  function reloadUpdatedApp() {
    if (reloadRequested) return;
    reloadRequested = true;
    location.reload();
  }

  async function update() {
    if (updateRecovery) {
      reloadUpdatedApp();
      return;
    }
    if (pendingUpdate || preparingUpdate) return;
    preparingUpdate = true;
    const button = document.getElementById("mobileUpdate"),
      previousFocus = document.activeElement;
    try {
      if (!registration?.waiting) {
        await registration?.update();
        if (!registration?.waiting) {
          updateMessage =
            "هنوز نسخه جدید برای اعمال آماده نیست؛ چند لحظه دیگر تلاش کنید.";
          paint();
          return;
        }
      }
      button.disabled = true;
      updateMessage = "در حال ذخیره ویرایش‌ها پیش از به‌روزرسانی…";
      paint();
      const prepare = window.EduV24?.prepareForUpdate;
      if (typeof prepare !== "function")
        throw Error(
          "برنامه برای ذخیرهٔ امن پیش از به‌روزرسانی آماده نیست؛ پس از آماده‌شدن دوباره تلاش کنید.",
        );
      await prepare();
      if (
        !confirm(
          "ویرایش‌های این پنجره ذخیره شدند. نسخه جدید در همین پنجره باز شود؟",
        )
      ) {
        updateMessage = "";
        button.disabled = false;
        paint();
        return;
      }
      // Confirmation may schedule another mutation. Drain the installation
      // again before asking the worker to replace this execution context.
      await prepare();
      lockUpdateSurface(previousFocus);
      pendingUpdate = true;
      updateMessage = "در حال اعمال نسخه جدید…";
      paint();
      updateTimer = setTimeout(() => {
        // skipWaiting cannot be canceled. Keep editors locked until a new
        // execution context opens, even when slow activation exceeds the watchdog.
        updateRecovery = true;
        button.disabled = false;
        updateMessage =
          "اعمال نسخه بیشتر از معمول طول کشیده؛ ویرایش‌ها ذخیره شده‌اند. «بازکردن دوباره برنامه» را بزنید.";
        paint();
      }, 15000);
      registration.waiting.postMessage({ type: "APPLY_UPDATE" });
    } catch (e) {
      clearTimeout(updateTimer);
      pendingUpdate = false;
      updateRecovery = false;
      button.disabled = false;
      unlockUpdateSurface();
      updateMessage = e.message || "ابتدا ویرایش‌های ذخیره‌نشده را بررسی کنید.";
      paint();
    } finally {
      preparingUpdate = false;
    }
  }

  window.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    installEvent = e;
    paint();
    paintInstallNotice();
  });
  window.addEventListener("appinstalled", () => {
    installEvent = null;
    rememberInstallNotice();
    closeInstallNotice();
    paint();
  });
  window.addEventListener("online", () => {
    paint();
    if (registration) status();
  });
  window.addEventListener("offline", paint);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && navigator.onLine)
      registration?.update().catch(() => {});
  });
  window.addEventListener("load", async () => {
    shell();
    firstVisitInstall();
    if (location.protocol === "file:") {
      text("فایل مستقل آفلاین؛ نصب استاندارد PWA از لینک امن انجام می‌شود.");
      return;
    }
    if (!("serviceWorker" in navigator) || !window.isSecureContext) {
      text("نصب آفلاین به مرورگر جدید و لینک HTTPS نیاز دارد.");
      return;
    }
    navigator.serviceWorker.addEventListener("controllerchange", () => {
      if (pendingUpdate) {
        clearTimeout(updateTimer);
        reloadUpdatedApp();
      } else status();
    });
    navigator.serviceWorker.addEventListener("message", (e) => {
      if (e.data?.type === "UPDATE_BLOCKED") {
        clearTimeout(updateTimer);
        pendingUpdate = false;
        updateRecovery = false;
        document.getElementById("mobileUpdate").disabled = false;
        unlockUpdateSurface();
        updateMessage = "به‌روزرسانی متوقف شد: برنامه در پنجره دیگری باز است.";
        paint();
        if (window.showModal)
          showModal(
            "به‌روزرسانی برنامه",
            '<div class="update-notice"><div class="update-notice-heading"><span class="update-notice-symbol" aria-hidden="true"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" focusable="false"><rect x="3" y="8" width="13" height="13" rx="2"/><path d="M8 8V5a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-3M3 12h13"/></svg></span><div><h4>پنجره‌های دیگر کلاس‌یار را ببندید</h4><p>برای نصب نسخهٔ جدید، فقط همین پنجره را باز نگه دارید.</p></div></div><ol class="update-notice-steps"><li><span aria-hidden="true">۱</span><p>ویرایش‌های پنجره‌های دیگر را ذخیره کنید.</p></li><li><span aria-hidden="true">۲</span><p>تب‌ها و پنجره‌های دیگر کلاس‌یار را ببندید؛ نسخهٔ نصب‌شده هم حساب می‌شود.</p></li><li><span aria-hidden="true">۳</span><p>به همین پنجره برگردید و «نسخه جدید آماده است» را بزنید.</p></li></ol><p class="update-notice-note"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg><span>نیازی به حذف برنامه یا پاک‌کردن اطلاعات مرورگر نیست.</span></p><div class="update-notice-actions"><button type="button" data-workspace-action="close"><span class="control-icon" aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" focusable="false"><path d="m5 12 4 4L19 6"/></svg></span><span>متوجه شدم</span></button></div></div>',
          );
      }
    });
    try {
      registration = await navigator.serviceWorker.register(
        "./service-worker.js",
        { updateViaCache: "none" },
      );
      function watchInstalling() {
        const worker = registration.installing;
        worker?.addEventListener("statechange", () => {
          if (worker.state === "installed") {
            paint();
            status();
          }
          if (worker.state === "redundant" && !offlineReady)
            text(
              "دانلود آفلاین کامل نشد؛ اینترنت را بررسی و دوباره تلاش کنید.",
            );
        });
      }
      registration.addEventListener("updatefound", watchInstalling);
      watchInstalling();
      await Promise.race([
        navigator.serviceWorker.ready,
        new Promise((_, reject) =>
          setTimeout(() => reject(Error("Offline setup timed out")), 30000),
        ),
      ]);
      await status();
      paint();
    } catch (e) {
      text(
        "آماده‌سازی آفلاین کامل نشد؛ اینترنت را بررسی و برنامه را دوباره باز کنید.",
      );
    }
  });
  window.EduPWA = {
    getStatus: () => ({
      offlineReady,
      waiting: !!registration?.waiting,
      installed:
        matchMedia("(display-mode: standalone)").matches ||
        !!navigator.standalone,
    }),
    help,
  };
})();
